      "**⑩ 導航、歷史與文學**——波爾（Pohl, Friedrich-Wilhelm）《Die Geschichte der Navigation》（Hamburg 2004）；索貝爾（Sobel, Dava）/Andrews《Längengrad. Die wahre Geschichte eines einsamen Genies, welches das größte wissenschaftliche Problem seiner Zeit löste》（Berlin 1999，插圖版；英文原著 Longitude）；褚威格（Zweig, Stefan）《Amerigo》（Stockholm 1944；Frankfurt 1995）；托爾斯泰（Tolstoi, Leo）《Anna Karenina》（München 1997）。",
      "**怎麼用這份書目（與各章對照）**：結束語的公司策略定義→烏爾里希《Unternehmungspolitik》（推定）；第1章亞美利哥與哥倫布的對照→褚威格《Amerigo》；第1章提到的 1997 年治理著作與 2002 年第3版→《Die Neue Corporate Governance》；第8章的可存活系統模型、嵌入與遞迴→比爾、阿什比、瓦雷拉；第5、8章提到的 18 世紀蘇格蘭道德哲學家與自發秩序→弗格森、海耶克；第9、10章的 PIMS 與顧客價值→Buzzell/Gale、Gale、PIMS-Letters；第10、13章的 S 曲線、替代與創新週期→馬爾凱蒂、莫迪斯、彭格、門施、艾格勒、格呂布勒；第10章的 20 面體會議模型→比爾《Beyond Dispute》的團隊協同（Team Syntegrity，推定）；第5、10章的仿生學與兩屆仿生學大會→⑧ 類；第17章的事業部責任→史隆。整體看來，書目的重心是**控制論與系統科學、聖加侖學派、仿生學與演化、S 曲線與擴散研究**，而不是主流的財務或公司法文獻——這本身就說明了作者把公司策略與治理放在「系統控制層面」的立場。"
