   "concepts": [
    {
     "zh": "公司策略",
     "en": "Corporate policy (Unternehmenspolitik)",
     "explain": "烏爾里希定義：規定企業未來較長時期經營活動的基本方針。本書把它展開為三項理念，並作為全局控制的核心。"
    },
    {
     "zh": "三項理念",
     "en": "The three concepts: enterprise, environment, management",
     "explain": "企業理念（企業應該做什麼）、環境理念（在什麼環境中運行）、企業管理理念（應當如何運行，第11章稱領導理念）；三者共同構成公司策略與「導航圖」。導航圖圖面：內圈三個圓（上企業管理、左下環境、右下企業）以六支箭頭兩兩雙向影響；外圈三個方塊（管理理念、環境理念、企業理念）各以直線連到對應的圓，彼此以雙向弧線圍成大圓。"
    },
    {
     "zh": "通用企業管理模型",
     "en": "General management model",
     "explain": "以戰略、結構、文化三個子系統，加上企業領導的指揮，使全局控制涉及整個企業；這些主題分散在馬利克管理系列的其他分冊。圖面：同心三環由外而內為環境、公司策略、治理；核心是三個交疊的子系統圓（上戰略、左下結構、右下文化），中央企業領導以箭頭指向三者；三個方位各有一串三支雙向箭頭逐層貫穿各環。與第2章圖2-2「高層管理的全局控制」相同（該圖中央作「管理人員」）。"
    },
    {
     "zh": "馬利克管理系統",
     "en": "Malik Management System",
     "explain": "作者以控制論為基礎、統一、動態、開放且相互聯繫的管理系統，涵蓋三個管理範疇；曾被稱為「管理之輪」「通用管理模型」「標準模型」等，但特徵由內容與版本而非名稱決定。"
    },
    {
     "zh": "三個管理範疇",
     "en": "Three dimensions of management",
     "explain": "（1）作為社會功能的管理；（2）機構組織意義上的管理；（3）人的行為意義上的管理。"
    },
    {
     "zh": "作業系統",
     "en": "Operating system (for complex institutions)",
     "explain": "簡中譯作「操作系統」。比喻馬利克管理系統是複雜機構發展的底層平台：模組可配置、調用、啟動，適用任何機構與個人，並與用戶共同演化，結合點是人腦。"
    },
    {
     "zh": "最少模組，最多應用",
     "en": "Minimum modules, maximum applications",
     "explain": "控制論原則：構建系統時讓最小數量的模組產生最大數量的應用形式；使用戶擁有自主權，系統成效取決於用戶的掌握程度。"
    },
    {
     "zh": "五項使用者介面",
     "en": "Five user interfaces",
     "explain": "控制論管理模型、工具、方法、理念、應用規則；分別回答看什麼、用什麼取得資訊、怎麼做、怎麼想、怎麼用得好。"
    },
    {
     "zh": "文明技術與文化技術",
     "en": "Civilizational and cultural techniques",
     "explain": "作者把管理系統定位為複雜性時代必要的新「文明技術和文化技術」；沒有它，資源無法被認識和轉換為成果。其知識形態是導航系統、模型、調節機制和工具。"
    },
    {
     "zh": "正確良好的管理",
     "en": "Right and good management",
     "explain": "作者的口號與專業標準（亦為其書名 Richtiges und gutes Management），用來區分真正的專業人士與追求表面、迎合大眾的冒牌高人。據書末參考文獻，《Richtiges und gutes Management: vom System zur Praxis》是 Krieg、Galler、Stadelmann 於 2005 年為馬利克所編的紀念文集（Festschrift）。"
    },
    {
     "zh": "導航圖",
     "en": "navigation map（暫譯）",
     "explain": "作者對「公司策略三項理念構成的系統」這張圖的稱呼，在第一部分扉頁、圖2-1、圖8-7、圖14-1 與結束語反覆出現，是全書的路線圖；第14章強調模型本身不做決策，而是在複雜系統的迷宮中定位、了解情況並提供行動指南的導航工具。"
    },
    {
     "zh": "企業領導（模型核心）",
     "en": "corporate leadership / general management（暫譯）",
     "explain": "通用企業管理模型中央的圓，位於戰略、結構、文化三片交疊花瓣的共同交集，以三支箭頭指向三者——全局控制透過「企業領導的指揮」擴及整個企業；第2章圖2-2 同一位置寫作「管理人員」。"
    },
    {
     "zh": "逐層雙向交換",
     "en": "layer-by-layer two-way coupling（暫譯）",
     "explain": "通用企業管理模型的讀圖要點：戰略、結構、文化各以一串雙向箭頭依序連到治理、公司策略、環境三層。治理與公司策略是包覆在外、雙向相通的框架，不是壓在上面的另一條命令鏈；環境變化向內傳導，子系統的結果向外回饋。"
    }
   ],
